import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { catchError, Observable, of, tap } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class TextToSpeechService {

  private synth: SpeechSynthesis | null = null;
  private _http = inject(HttpClient)
  private _resUrl = "ai/response.json";
  private _resData: any;

  constructor() {
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      this.synth = window.speechSynthesis;
    }
    this.loadResponses().subscribe();
    //console.log('Loding log from here')
  }

  speakTask(text: string, lang: string = 'en-US', rate: number = 1.0, pitch: number = 1.0): Promise<void> {
    if (!this.synth) {
      console.log('Speech synthesis is not supported in this browser.');
      return Promise.resolve();
    }
    this.synth.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = lang;
    utterance.rate = rate;   // Speed: 0.1 to 10
    utterance.pitch = pitch; // Pitch: 0 to 2
    this.synth.speak(utterance);
    return new Promise((resolve) => {
      utterance.onend = () => {
        resolve();
      };
    });
  }

  // Speak a given text string
  speak(text: string, lang: string = 'en-US', rate: number = 1.0, pitch: number = 1.0): void {
    if (!this.synth) {
      console.warn('Speech synthesis is not supported in this browser.');
      return;
    }

    // Stop any ongoing speech before starting a new one
    this.synth.cancel();
    if (this._resData) {
      const utterance = new SpeechSynthesisUtterance(this.getReplyText(text));
      utterance.lang = lang;
      utterance.rate = rate;   // Speed: 0.1 to 10
      utterance.pitch = pitch; // Pitch: 0 to 2
      this.synth.speak(utterance);
    } else {
      this.loadResponses(text).subscribe();
    }
  }

  toggle() {
    if (this.synth) {
      if (this.synth.speaking) {
        if (this.synth.paused) {
          this.synth.resume();
        } else {
          this.synth.pause();
        }
      }
    }
  }

  /*pause(): void {
    if (this.synth && this.synth.speaking && !this.synth.paused) {
      this.synth.pause();
    }
  }

  resume(): void {console.log('Resume called')
    if (this.synth) {
      
     this.synth.resume();
    }
  }*/

  // Stop speaking
  stop(): void {
    if (this.synth) {
      this.synth.cancel();
    }
  }

  // Retrieve available voices from the user's browser
  getVoices(): SpeechSynthesisVoice[] {
    return this.synth ? this.synth.getVoices() : [];
  }

  private loadResponses(text: string = '') {
    if (this._resData) {
      return of(this._resData); 
    } else {
      return this._http.get<any>(this._resUrl)
        .pipe(
          tap((data) => {
            this._resData = data;
            if (text != '') this.speak(text)
          }),
          catchError(this.handleError('error with getting module info', []))
        )
    }
  }

  private getReplyText(text: string): string {
    console.log(text, this._resData)
    let i: number;
    if (this._resData) {
      i = (this._resData.general.ques as Array<string>).findIndex(d => text.indexOf(d) > -1);
      if (i > -1) return this._resData.general.ans[i] as string;
    }
    return 'We not able to understand this, please send us an email through suppoprt option under profile. Hum apka prashna samajh nahi pa rahe,  Kripya profile se support option use kar ke, hume email bhejiye.';
  }

  /**
   * Handle Http operation that failed.
   * Let the app continue.
   * @param operation - name of the operation that failed
   * @param result - optional value to return as the observable result
   */
  private handleError<T>(operation = 'operation', result?: T) {
    return (error: any): Observable<T> => {

      // TODO: send the error to remote logging infrastructure
      console.error(error); // log to console instead

      // TODO: better job of transforming error for user consumption
      console.log(`${operation} failed: ${error.message}`);

      // Let the app keep running by returning an empty result.
      return of(result as T);
    };
  }



}
