import { Injectable } from '@angular/core';
import { Observable, Subject } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class SpeechRecognitionService {
  private recognition: any;
  private transcript$ = new Subject<{ id: string, text: string }>();
  private isListening = false;
  private listener_Id: string = '';

  constructor() {
    // Fallback support for Chrome vs other browsers
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    
    if (SpeechRecognition) {
      this.recognition = new SpeechRecognition();
      this.recognition.continuous = true;       // Keep listening even if the user pauses
      this.recognition.interimResults = true;   // Show real-time partial text while speaking
      this.recognition.lang = 'en-US';          // Set target locale

      // Process real-time results
      this.recognition.onresult = (event: any) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            finalTranscript += event.results[i][0].transcript;
          }
        }
        if (finalTranscript) {
          this.transcript$.next({ id: this.listener_Id, text: finalTranscript });
        }
      };

      this.recognition.onerror = (event: any) => {
        console.error('Speech recognition error:', event.error);
      };
    } else {
      console.warn('Web Speech API is not supported in this browser.');
    }
  }

  getTranscript(): Observable<{ id: string, text: string }> {
    return this.transcript$.asObservable();
  }

  start(id: string): void {
    if (this.recognition && !this.isListening) {
      this.recognition.start();
      this.isListening = true;
      this.listener_Id = id;
    }
  }

  stop(): void {
    if (this.recognition && this.isListening) {
      this.recognition.stop();
      this.isListening = false;
    }
  }
}
